    dx0, dy0 = coord(depot)

    def ang_key(did):
        x, y = coord(did)
        dx = x - dx0
        dy = y - dy0
        if dx == 0 and dy == 0:
            q, s = 0, 0.0
        elif dx >= 0 and dy >= 0:
            q, s = 0, dy / (abs(dx) + abs(dy) + 1e-12)
        elif dx < 0 <= dy:
            q, s = 1, (-dx) / (abs(dx) + abs(dy) + 1e-12)
        elif dx <= 0 and dy < 0:
            q, s = 2, (-dy) / (abs(dx) + abs(dy) + 1e-12)
        else:
            q, s = 3, dx / (abs(dx) + abs(dy) + 1e-12)
        return (q + s, dx * dx + dy * dy, did)

    total = 0
    for i in ids:
        total += demand(i)
    if not cap or cap <= 0:
        cap = max(1, total)

    ordered = sorted(ids, key=ang_key)
    routes, cur, load = [], [], 0
    for c in ordered:
        dc = demand(c)
        if dc > cap:
            if cur:
                routes.append(cur)
                cur, load = [], 0
            routes.append([c])
        elif load + dc <= cap:
            cur.append(c)
            load += dc
        else:
            routes.append(cur)
            cur, load = [c], dc
    if cur:
        routes.append(cur)

    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    clean = []
    used = set()
    for r in routes:
        nr = []
        for c in r:
            if c in ids and c not in used:
                used.add(c)
                nr.append(c)
        if nr:
            clean.append(nr)
    for c in ids:
        if c not in used:
            clean.append([c])
    routes = clean

    def rload(r):
        s = 0
        for c in r:
            s += demand(c)
        return s

    def ins_cost(r, p, c):
        a = depot if p == 0 else r[p - 1]
        b = depot if p == len(r) else r[p]
        return d(a, c) + d(c, b) - d(a, b)

    def two_opt(r):
        n = len(r)
        if n < 4:
            return r
        improved = True
        while improved:
            improved = False
            best = 0
            bi = bj = None
            for i in range(n - 1):
                a = depot if i == 0 else r[i - 1]
                b = r[i]
                for j in range(i + 1, n):
                    c = r[j]
                    e = depot if j == n - 1 else r[j + 1]
                    gain = (d(a, b) + d(c, e)) - (d(a, c) + d(b, e))
                    if gain > best + 1e-12:
                        best = gain
                        bi, bj = i, j
            if bi is not None:
                r = r[:bi] + list(reversed(r[bi:bj + 1])) + r[bj + 1:]
                improved = True
        return r

    routes = [two_opt(r[:]) for r in routes if r]

    changed = True
    while changed:
        changed = False
        best = None
        best_delta = 0
        loads = [rload(r) for r in routes]
        for i, r1 in enumerate(routes):
            for p, c in enumerate(r1):
                dc = demand(c)
                rem_a = depot if p == 0 else r1[p - 1]
                rem_b = depot if p == len(r1) - 1 else r1[p + 1]
                rem = d(rem_a, c) + d(c, rem_b) - d(rem_a, rem_b)
                for j, r2 in enumerate(routes):
                    if i == j or loads[j] + dc > cap:
                        continue
                    for q in range(len(r2) + 1):
                        delta = rem - ins_cost(r2, q, c)
                        if delta > best_delta + 1e-12:
                            best_delta = delta
                            best = (i, p, j, q, c)
        if best is not None:
            i, p, j, q, c = best
            if i < j:
                routes[i].pop(p)
                routes[j].insert(q, c)
            else:
                routes[j].insert(q, c)
                routes[i].pop(p)
            routes = [r for r in routes if r]
            changed = True

    routes = [r for r in routes if r]
    routes.sort(key=lambda r: (str(r[0]), len(r), tuple(str(x) for x in r)))
    return routes
